"""Self-contained local viewer. No network requests or third-party assets."""
import json

def render(report):
    data = json.dumps(report, allow_nan=False, separators=(',', ':')).replace('<', '\\u003c').replace('>', '\\u003e').replace('&', '\\u0026')
    return TEMPLATE.replace('__REPORT_DATA__', data)

TEMPLATE = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Toolpath inspector</title><style>
:root{color-scheme:light;--bg:#f4f6fa;--ink:#172b43;--muted:#52647b;--border:#d4dce6;--blue:#164cba;--orange:#bc4b13}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.5 system-ui,sans-serif}main{max-width:1500px;margin:auto;padding:28px}h1{font-size:30px;letter-spacing:-1px;margin:0}h2{font-size:19px;margin:0 0 12px}p{margin:8px 0;color:var(--muted)}header{margin-bottom:22px}.eyebrow{font-size:12px;letter-spacing:2px;font-weight:700;color:var(--blue)}.cards{display:flex;flex-wrap:wrap;gap:12px;margin:20px 0}.card{padding:12px 18px;background:white;border:1px solid var(--border);border-radius:10px;flex:1;min-width:140px}.card strong{display:block;font-size:24px}.card span{font-size:13px;color:var(--muted)}.toolbar{display:flex;gap:16px;flex-wrap:wrap;align-items:end;margin-bottom:16px}label{display:block;font-weight:600;font-size:14px}select,button,input{font:inherit}select,button{min-height:44px;border:1px solid var(--border);border-radius:7px;background:white;color:var(--ink);padding:8px 12px}button{cursor:pointer}button:hover{background:#e8effc}:focus-visible{outline:3px solid var(--blue);outline-offset:3px}.layout{display:grid;grid-template-columns:minmax(0,1fr) 350px;gap:16px}.panel{background:white;border:1px solid var(--border);border-radius:12px;padding:18px;min-width:0}canvas{width:100%;height:520px;display:block;touch-action:manipulation;border:1px solid var(--border);border-radius:8px}#legend{font-size:14px;margin:10px 0}.ramp{display:inline-block;width:130px;height:10px;background:linear-gradient(90deg,#164cba,#bc4b13);margin:0 8px}.selection{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-top:12px}.selection input{flex:1;min-width:100px;min-height:44px}.detail{white-space:pre-wrap;overflow-wrap:anywhere;font:13px/1.65 ui-monospace,monospace;background:#f5f7fa;padding:12px;border-radius:8px;margin-top:10px;max-height:540px;overflow:auto}.notice{border-left:3px solid #d28135;padding:8px 12px;font-size:14px;background:#fff8ef}.small{font-size:13px}details{margin-top:18px}summary{cursor:pointer;min-height:44px;padding:8px 0;font-weight:600}#empty{padding:15px;color:var(--muted)}input[type=checkbox]{width:20px;height:20px;vertical-align:middle}footer{margin-top:20px;font-size:13px;color:var(--muted)}@media(max-width:900px){.layout{grid-template-columns:1fr}main{padding:16px}canvas{height:380px}.detail{max-height:400px}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto}}
</style></head><body><main>
<header><div class="eyebrow">AESTHETICS / TOOLPATH ANALYSIS</div><h1>Inspect the path behind the finish</h1><p>Explore commanded geometry and extrusion history. This report contains no measured motion, pressure or temperature.</p></header>
<div class="cards"><div class="card"><strong id="moves">0</strong><span>Parsed moves</span></div><div class="card"><strong id="geometry">0</strong><span>Known endpoint geometry</span></div><div class="card"><strong id="entries">0</strong><span>Cosmetic entries</span></div><div class="card"><strong id="barriers">0</strong><span>Unsupported commands</span></div></div>
<div class="toolbar"><div><label for="layer">Layer</label><select id="layer"></select></div><div><label for="metric">Color by</label><select id="metric"><option value="length_mm">Segment length · mm</option><option value="effective_requested_speed_mm_s">Requested speed × override · mm/s</option><option value="nominal_filament_speed_mm_s">Nominal filament speed · mm/s</option><option value="curvature">Fitted / commanded curvature · 1/mm</option><option value="fan_speed">Commanded fan · fraction</option><option value="hotend_target_c">Hotend target · °C</option></select></div><label><input type="checkbox" id="travel"> Show travel</label><button id="reset">Reset view</button><button id="download">Save JSON</button></div>
<div class="layout"><section class="panel" aria-label="Layer plot"><canvas id="plot" tabindex="0" aria-label="XY toolpath plot. Click a path to inspect it, or use the move slider and previous and next buttons below."></canvas><div id="empty" hidden>No known paths on this layer. Check unsupported commands and coordinate setup.</div><div id="legend"></div><p class="small">XY projection in millimeters. Circles mark cosmetic entries; selected path is black. Gray dashes indicate unknown values or travel. Click a path, or use the controls below.</p><div class="selection"><button id="prev" aria-label="Previous move">Previous</button><label for="move">Move</label><input id="move" type="range" min="0" max="0" value="0"><button id="next" aria-label="Next move">Next</button><span id="position" aria-live="polite"></span></div></section>
<aside class="panel"><h2>Path context</h2><p id="selected" aria-live="polite">Select a path.</p><div class="notice">Missing values mean unknown. Timing uses requested speed; acceleration and firmware look-ahead are not simulated.</div><div id="detail" class="detail"></div></aside></div>
<details><summary>Coverage, assumptions and unsupported commands</summary><div id="coverage" class="detail"></div></details><footer>Self-contained local report. Nothing is uploaded. Curve fits and firmware subdivision counts are estimates.</footer>
</main><script type="application/json" id="report">__REPORT_DATA__</script><script>
'use strict';
const report=JSON.parse(document.getElementById('report').textContent), $=id=>document.getElementById(id);
const source=report.spatial_moves||[], events=new Map(report.cosmetic_entries.map(e=>[e.entry.line,e]));
const curves=[];for(const path of report.resolution.linear_deposition_paths)for(const c of path.fitted_curves)curves.push(c);
let curveIndex=0;for(const m of source){while(curveIndex<curves.length&&curves[curveIndex].end_line<m.line)curveIndex++;let c=curves[curveIndex];m.curvature=m.arc?1/m.arc.radius_mm:c&&c.start_line<=m.line&&c.end_line>=m.line?1/c.radius_mm:null;}
$('moves').textContent=report.coverage.total_moves.toLocaleString();$('geometry').textContent=report.coverage.known_geometry_moves.toLocaleString();$('entries').textContent=report.coverage.cosmetic_entries.toLocaleString();$('barriers').textContent=report.coverage.unsupported_commands.toLocaleString();
$('coverage').textContent=JSON.stringify({assumptions:report.assumptions,coverage:report.coverage,unsupported_commands:report.unsupported_commands},null,2);
const layerKey=m=>m.layer===null?'unknown':String(m.layer), keys=[...new Set(source.map(layerKey))];
for(const key of keys){const o=document.createElement('option');o.value=key;o.textContent=key==='unknown'?'Before layer marker / unknown':`Layer ${key} (zero-based)`;$('layer').append(o);}
let visible=[], paths=[], selected=0, bounds, scale, offset, low=0, high=1;
const canvas=$('plot'), ctx=canvas.getContext('2d');
const known=m=>m.start_xyz&&m.end_xyz&&[...m.start_xyz,...m.end_xyz].every(Number.isFinite);
function points(m){if(!m.arc)return[m.start_xyz,m.end_xyz];const a=m.arc,c=a.center_xy_mm,start=Math.atan2(m.start_xyz[1]-c[1],m.start_xyz[0]-c[0]),sweep=a.sweep_degrees*Math.PI/180*(a.direction==='cw'?-1:1),count=Math.min(256,Math.max(8,Math.ceil(a.sweep_degrees/3)));return Array.from({length:count+1},(_,i)=>i===count?m.end_xyz:[c[0]+a.radius_mm*Math.cos(start+sweep*i/count),c[1]+a.radius_mm*Math.sin(start+sweep*i/count)]);}
function value(m){const k=$('metric').value;return ['fan_speed','hotend_target_c'].includes(k)?m.commanded_state[k]:m[k];}
function color(v){if(!Number.isFinite(v))return '#768398';let t=high===low?.5:(v-low)/(high-low);return `rgb(${Math.round(22+166*t)},${Math.round(76-t)},${Math.round(186-167*t)})`;}
function screen(p){return[offset[0]+(p[0]-bounds[0])*scale,offset[1]-(p[1]-bounds[1])*scale];}
function chooseLayer(){visible=source.filter(m=>layerKey(m)===$('layer').value&&known(m)&&m.length_mm>0&&($('travel').checked||m.extrusion_mm>0));paths=visible.map(points);selected=0;$('move').max=Math.max(0,visible.length-1);$('move').value=0;$('move').disabled=!visible.length;draw();inspect();}
function draw(){const rect=canvas.getBoundingClientRect(),dpr=window.devicePixelRatio||1;canvas.width=rect.width*dpr;canvas.height=rect.height*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,rect.width,rect.height);$('empty').hidden=!!visible.length;if(!visible.length){$('legend').textContent='No analyzable paths';return;}let xmin=Infinity,ymin=Infinity,xmax=-Infinity,ymax=-Infinity;for(const path of paths)for(const p of path){xmin=Math.min(xmin,p[0]);xmax=Math.max(xmax,p[0]);ymin=Math.min(ymin,p[1]);ymax=Math.max(ymax,p[1]);}bounds=[xmin,ymin,xmax,ymax];scale=Math.min((rect.width-70)/Math.max(1,xmax-xmin),(rect.height-70)/Math.max(1,ymax-ymin));offset=[(rect.width-(xmax-xmin)*scale)/2,(rect.height+(ymax-ymin)*scale)/2];const vals=visible.map(value).filter(Number.isFinite);low=vals.length?vals.reduce((a,b)=>Math.min(a,b)):0;high=vals.length?vals.reduce((a,b)=>Math.max(a,b)):1;$('legend').replaceChildren(document.createTextNode(vals.length?`${low.toFixed(3)} `:'Unknown '));const ramp=document.createElement('span');ramp.className='ramp';$('legend').append(ramp,document.createTextNode(vals.length?` ${high.toFixed(3)} · layer-local scale`:' · no known values'));
for(let i=0;i<visible.length;i++){const m=visible[i],coords=paths[i].map(screen);ctx.beginPath();ctx.moveTo(...coords[0]);for(const p of coords.slice(1))ctx.lineTo(...p);ctx.strokeStyle=i===selected?'#101927':color(value(m));ctx.lineWidth=i===selected?4:2;ctx.setLineDash(!Number.isFinite(value(m))||!(m.extrusion_mm>0)?[4,4]:[]);ctx.stroke();if(events.has(m.line)){ctx.setLineDash([]);ctx.beginPath();ctx.arc(...coords[0],4,0,2*Math.PI);ctx.strokeStyle='#172b43';ctx.stroke();}}
ctx.setLineDash([]);ctx.fillStyle='#52647b';ctx.font='12px system-ui';ctx.fillText(`X ${xmin.toFixed(1)} → ${xmax.toFixed(1)} mm`,12,rect.height-10);ctx.fillText(`Y ${ymin.toFixed(1)} → ${ymax.toFixed(1)} mm`,12,18);}
function inspect(){const m=visible[selected];$('position').textContent=m?`${selected+1} / ${visible.length}`:'0 / 0';$('prev').disabled=!m||selected===0;$('next').disabled=!m||selected===visible.length-1;if(!m){$('selected').textContent='No path selected.';$('detail').textContent='';return;}$('selected').textContent=`Line ${m.line} · ${m.feature} · ${m.command}`;const e=events.get(m.line);$('detail').textContent=JSON.stringify({start_xyz:m.start_xyz,end_xyz:m.end_xyz,length_mm:m.length_mm,requested_speed_mm_s:m.requested_speed_mm_s,effective_requested_speed_mm_s:m.effective_requested_speed_mm_s,raw_extrusion_mm:m.extrusion_mm,effective_extrusion_mm:m.effective_extrusion_mm,nominal_filament_speed_mm_s:m.nominal_filament_speed_mm_s,commanded_state:m.commanded_state,cosmetic_entry_history:e?e.history:'Select a circled cosmetic entry to inspect its history.',arc:m.arc},null,2);}
function select(i){selected=Math.max(0,Math.min(visible.length-1,i));$('move').value=selected;draw();inspect();}
$('layer').onchange=chooseLayer;$('travel').onchange=chooseLayer;$('metric').onchange=draw;$('reset').onclick=chooseLayer;$('move').oninput=()=>select(Number($('move').value));$('prev').onclick=()=>select(selected-1);$('next').onclick=()=>select(selected+1);canvas.onkeydown=e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();select(selected+(e.key==='ArrowRight'?1:-1));}};
canvas.onclick=e=>{const r=canvas.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;let best=Infinity,index=-1;paths.forEach((path,i)=>{let pts=path.map(screen);for(let j=1;j<pts.length;j++){const a=pts[j-1],b=pts[j],dx=b[0]-a[0],dy=b[1]-a[1],d=dx*dx+dy*dy,t=d?Math.max(0,Math.min(1,((x-a[0])*dx+(y-a[1])*dy)/d)):0,dist=Math.hypot(x-a[0]-t*dx,y-a[1]-t*dy);if(dist<best){best=dist;index=i;}}});if(index>=0&&best<20)select(index);};
$('download').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(report,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='toolpath-report.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
const first=source.find(m=>known(m)&&m.length_mm>0&&m.extrusion_mm>0);if(first)$('layer').value=layerKey(first);new ResizeObserver(()=>draw()).observe(canvas);chooseLayer();
</script></body></html>'''
